import {createDemo,initialDraft,samples,validateDraft} from './staff-demo-model.js?v=20261027-1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountDemo(root){
 const model=createDemo();let draft=initialDraft(),editing=null,preview=false,status='';
 const $=s=>root.querySelector(s);
 function focus(s){$(s)?.focus();}
 function card(p,actions=false){const sample=samples[p.photo];return '<article class="demo-card">'+(sample.src?'<img src="'+sample.src+'" alt="'+sample.label+'（架空の商品イラスト）">':'')+'<div class="demo-card-content"><span class="demo-badge '+(p.state==='ended'?'ended':'')+'">'+(p.state==='ended'?'終了しました（デモ）':'掲載イメージ（デモ）')+'</span><h3>'+esc(p.title)+'</h3><p class="demo-body">'+esc(p.text)+'</p>'+(actions?'<div class="actions"><button class="quiet" data-edit="'+p.id+'">編集する</button><button class="quiet" data-end="'+p.id+'" '+(p.state==='ended'?'disabled':'')+'>終了にする</button></div>':'')+'</div></article>';}
 function capture(){draft={title:$('#demo-title').value,text:$('#demo-text').value,photo:root.querySelector('input[name=sample]:checked')?.value||'none'};}
 function render(target){const posts=model.list();root.innerHTML='<p class="demo-status" role="status" aria-live="polite" aria-atomic="true">'+esc(status)+'</p><div class="demo-grid"><section class="demo-panel" aria-labelledby="compose-heading"><p class="step-label">'+(preview?'2 / 2　見え方を確認':'1 / 2　お知らせをつくる')+'</p><h2 id="compose-heading" tabindex="-1">'+(preview?'この内容で試しますか？':editing?'デモの投稿を編集':'まずは文章と写真を選ぶ')+'</h2>'+(preview?card({...draft,state:'active'})+'<p class="demo-small">「デモ投稿する」を押すと、右側（スマホでは下）の一覧に追加されます。本番には公開されません。</p><div class="actions"><button id="demo-publish">デモ投稿する</button><button id="demo-back" class="quiet">内容に戻る</button></div>':'<form id="demo-form" novalidate><label for="demo-title">見出し（必須・40文字まで）</label><input id="demo-title" maxlength="40" required value="'+esc(draft.title)+'" aria-describedby="demo-error"><label for="demo-text">本文（必須・180文字まで）</label><textarea id="demo-text" maxlength="180" required aria-describedby="demo-counter demo-error">'+esc(draft.text)+'</textarea><p id="demo-counter" class="counter">'+draft.text.length+' / 180文字</p><fieldset><legend>写真の見本を選ぶ</legend><div class="sample-options">'+Object.entries(samples).map(([key,s])=>'<label class="sample-option"><input type="radio" name="sample" value="'+key+'" '+(draft.photo===key?'checked':'')+'>'+s.label+'</label>').join('')+'</div></fieldset><div id="sample-image">'+(samples[draft.photo].src?'<img class="sample-thumb" src="'+samples[draft.photo].src+'" alt="選択中：'+samples[draft.photo].label+'（架空の商品イラスト）">':'<p class="demo-small">写真なしでも投稿できます。</p>')+'</div><button type="submit">見え方を確認する →</button></form>')+'<p id="demo-error" role="alert"></p></section><section class="demo-panel" aria-labelledby="list-heading"><p class="step-label">お客さまに見える画面のイメージ</p><h2 id="list-heading" tabindex="-1">サンプル商店のお知らせ</h2><p class="demo-small">この画面だけの体験用一覧です（'+posts.length+' / 5件）。</p>'+(posts.length?posts.map(p=>card(p,true)).join(''):'<p class="demo-empty">まだデモ投稿はありません。文章と写真を選んで、見え方を試してみましょう。</p>')+'<button id="demo-new" class="quiet">新しいデモ投稿をつくる</button><div class="reset-area"><button id="demo-reset" class="quiet">デモを最初からやり直す</button><div class="reset-confirm" hidden><p>入力中の内容とデモ投稿を消して、最初に戻しますか？</p><div class="actions"><button id="reset-yes">最初に戻す</button><button id="reset-no" class="quiet">戻さない</button></div></div></div></section></div>';
 if(!preview){$('#demo-form').onsubmit=e=>{e.preventDefault();capture();try{draft=validateDraft(draft);preview=true;status='';render('#compose-heading');}catch(error){$('#demo-error').textContent=error.message;focus(!draft.title.trim()?'#demo-title':'#demo-text');}};$('#demo-text').oninput=()=>{$('#demo-counter').textContent=$('#demo-text').value.length+' / 180文字';};for(const r of root.querySelectorAll('input[name=sample]'))r.onchange=()=>{capture();const s=samples[draft.photo];$('#sample-image').innerHTML=s.src?'<img class="sample-thumb" src="'+s.src+'" alt="選択中：'+s.label+'（架空の商品イラスト）">':'<p class="demo-small">写真なしでも投稿できます。</p>';};}
 else{$('#demo-back').onclick=()=>{preview=false;render('#compose-heading');};$('#demo-publish').onclick=()=>{try{model.save(draft,editing);status=editing?'デモの投稿を更新しました。本番には公開されません。':'デモの一覧に追加しました。本番には公開されません。';draft=initialDraft();editing=null;preview=false;render('#list-heading');}catch(error){$('#demo-error').textContent=error.message;}};}
 for(const b of root.querySelectorAll('[data-edit]'))b.onclick=()=>{editing=Number(b.dataset.edit);draft=model.list().find(p=>p.id===editing);preview=false;status='デモの投稿を編集中です。';render('#compose-heading');};
 for(const b of root.querySelectorAll('[data-end]'))b.onclick=()=>{model.end(Number(b.dataset.end));status='終了した表示に切り替えました。デモの写真と文章は残ります。';render('#list-heading');};
 $('#demo-new').onclick=()=>{draft=initialDraft();editing=null;preview=false;status='新しいデモ投稿です。';render('#compose-heading');};
 $('#demo-reset').onclick=()=>{$('.reset-confirm').hidden=false;focus('#reset-no');};$('#reset-no').onclick=()=>{$('.reset-confirm').hidden=true;focus('#demo-reset');};$('#reset-yes').onclick=()=>{model.reset();draft=initialDraft();editing=null;preview=false;status='デモを最初の状態に戻しました。';render('#compose-heading');};
 if(target)focus(target);
 }
 render();return ()=>{root.replaceChildren();};
}
if(typeof document!=='undefined'){const root=document.querySelector('#demo-workspace');if(root)mountDemo(root);}
